const body = $json.body ?? $json;

const openrouterApiKey = ($env.OPENROUTER_API_KEY || '').trim();
const transcriptApiUrl = ($env.YT_TRANSCRIPT_API_URL || '').trim();
const transcriptApiKey = ($env.YT_TRANSCRIPT_API_KEY || '').trim();
const transcriptApiHost = ($env.YT_TRANSCRIPT_API_HOST || '').trim();
const telegramBotToken = ($env.TELEGRAM_BOT_TOKEN || '').trim();
const defaultChatId = ($env.TELEGRAM_CHAT_ID || '').trim();
const openclawWebhookUrl = ($env.OPENCLAW_YT_WEBHOOK_URL || 'http://127.0.0.1:5678/webhook/openclaw-youtube-backlog').trim();
const summaryModel = ($env.OPENROUTER_SUMMARY_MODEL || 'google/gemini-3-flash-preview').trim();

if (!openrouterApiKey) {
  throw new Error('Falta OPENROUTER_API_KEY en variables de entorno de n8n');
}
if (!transcriptApiUrl || !transcriptApiKey) {
  throw new Error('Faltan YT_TRANSCRIPT_API_URL y/o YT_TRANSCRIPT_API_KEY en variables de entorno de n8n');
}

const inputVideos = body.videos ?? body.video_urls ?? body.urls ?? body.videos_text ?? '';
let urls = [];
if (Array.isArray(inputVideos)) {
  urls = inputVideos.map((v) => (typeof v === 'string' ? v : String(v?.url || v?.video || ''))).filter(Boolean);
} else if (typeof inputVideos === 'string') {
  urls = inputVideos
    .split(/[\n,;]+/)
    .map((x) => x.trim())
    .filter(Boolean);
}
if (!urls.length && typeof body.url === 'string' && body.url.trim()) {
  urls = [body.url.trim()];
}
if (!urls.length) {
  throw new Error('No llegaron videos. Envia {"videos":["https://youtube.com/watch?v=..."]}');
}

const chatId = String(body.chat_id || body.telegram_chat_id || defaultChatId || '').trim();
if (!chatId) {
  throw new Error('Falta chat_id (payload) o TELEGRAM_CHAT_ID (env)');
}
if (!telegramBotToken) {
  throw new Error('Falta TELEGRAM_BOT_TOKEN en variables de entorno de n8n');
}

function extractVideoId(url) {
  try {
    const u = new URL(url);
    if (u.hostname.includes('youtu.be')) return u.pathname.replace('/', '').trim();
    if (u.searchParams.get('v')) return u.searchParams.get('v');
    const parts = u.pathname.split('/').filter(Boolean);
    const shortsIdx = parts.indexOf('shorts');
    if (shortsIdx >= 0 && parts[shortsIdx + 1]) return parts[shortsIdx + 1];
    return '';
  } catch {
    return '';
  }
}

function textFromAny(value) {
  if (!value) return '';
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map((x) => textFromAny(x)).filter(Boolean).join(' ');
  if (typeof value === 'object') {
    const keys = ['text', 'transcript', 'content', 'caption', 'line'];
    for (const k of keys) {
      if (value[k]) return textFromAny(value[k]);
    }
    return '';
  }
  return '';
}

function transcriptFromPayload(payload) {
  if (!payload) return '';
  const direct = textFromAny(payload);
  if (typeof payload === 'string') return payload;

  const candidates = [
    payload.transcript,
    payload.data,
    payload.captions,
    payload.subtitles,
    payload.result,
    payload.items,
    payload.segments,
  ];

  for (const c of candidates) {
    if (!c) continue;
    if (typeof c === 'string') return c;
    if (Array.isArray(c)) {
      const arrText = c
        .map((item) => {
          if (typeof item === 'string') return item;
          if (item && typeof item === 'object') return item.text || item.caption || item.line || item.content || '';
          return '';
        })
        .filter(Boolean)
        .join(' ');
      if (arrText) return arrText;
    }
    if (c && typeof c === 'object') {
      const objText = textFromAny(c);
      if (objText) return objText;
    }
  }

  return direct || '';
}

async function fetchJson(url, options = {}) {
  const res = await fetch(url, options);
  const txt = await res.text();
  let json = null;
  try { json = JSON.parse(txt); } catch {}
  if (!res.ok) {
    const msg = (json?.error?.message || json?.message || txt || `HTTP ${res.status}`).slice(0, 500);
    throw new Error(msg);
  }
  return json ?? txt;
}

async function summarizeVideo(url) {
  const videoId = extractVideoId(url);
  if (!videoId) throw new Error('No pude extraer videoId');

  const transcriptPayload = await fetchJson(transcriptApiUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-rapidapi-key': transcriptApiKey,
      ...(transcriptApiHost ? { 'x-rapidapi-host': transcriptApiHost } : {}),
    },
    body: JSON.stringify({ video_id: videoId, url }),
  });

  const transcriptRaw = transcriptFromPayload(transcriptPayload);
  const transcript = transcriptRaw.replace(/\s+/g, ' ').trim();
  if (!transcript) throw new Error('Transcript vacío/no disponible');

  const maxChars = Number(body.max_transcript_chars || 16000);
  const trimmedTranscript = transcript.slice(0, maxChars);

  const prompt = [
    'Resume este video de YouTube en español claro y accionable.',
    'Salida obligatoria:',
    '1) Resumen ejecutivo (5 bullets)',
    '2) Ideas clave',
    '3) Acciones recomendadas (si aplica)',
    '4) 3 frases para compartir en Twitter/LinkedIn',
    `URL: ${url}`,
    '',
    'TRANSCRIPT:',
    trimmedTranscript,
  ].join('\n');

  const completion = await fetchJson('https://openrouter.ai/api/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${openrouterApiKey}`,
      'HTTP-Referer': 'https://n8n.local',
      'X-Title': 'OpenClaw YouTube Summaries',
    },
    body: JSON.stringify({
      model: summaryModel,
      temperature: 0.2,
      max_tokens: Number(body.max_tokens || 900),
      messages: [
        { role: 'system', content: 'Eres un analista experto en resumen de contenido audiovisual.' },
        { role: 'user', content: prompt },
      ],
    }),
  });

  const summary = completion?.choices?.[0]?.message?.content || 'Sin resumen';
  const usage = completion?.usage || {};

  const telegramMessage = [
    '📺 *Resumen YouTube*',
    `🔗 ${url}`,
    '',
    summary,
    '',
    `[pub:openclaw|trigger:n8n] modelo: ${summaryModel}`
  ].join('\n');

  await fetchJson(`https://api.telegram.org/bot${telegramBotToken}/sendMessage`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      chat_id: chatId,
      text: telegramMessage.slice(0, 3900),
      parse_mode: 'Markdown',
      disable_web_page_preview: true,
    }),
  });

  try {
    await fetch(openclawWebhookUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        kind: 'youtube_summary',
        timestamp: new Date().toISOString(),
        source: 'n8n',
        model: summaryModel,
        file: `youtube-summary-${videoId}.md`,
        content: summary,
        meta: { url, videoId, usage },
      }),
    });
  } catch {}

  return {
    ok: true,
    url,
    videoId,
    model: summaryModel,
    transcriptChars: trimmedTranscript.length,
    usage,
    summary,
  };
}

const results = [];
for (const url of urls) {
  try {
    const r = await summarizeVideo(url);
    results.push(r);
  } catch (error) {
    const errText = String(error?.message || error);
    results.push({ ok: false, url, error: errText });
    try {
      await fetch(`https://api.telegram.org/bot${telegramBotToken}/sendMessage`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chat_id: chatId,
          text: `❌ No pude resumir ${url}\nError: ${errText}`,
          disable_web_page_preview: true,
        }),
      });
    } catch {}
  }
}

const okCount = results.filter((r) => r.ok).length;
const failCount = results.length - okCount;
return [{
  json: {
    kind: 'youtube_summary_batch',
    timestamp: new Date().toISOString(),
    total: results.length,
    okCount,
    failCount,
    results,
  },
}];
